    {"reference_id": "R1", "candidate_id": "C4", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "Water does not spout.", "candidate_evidence": "A small dorsal protrusion/fin appears abruptly on the back ridge and shifts shape inconsistently relative to the body mass.", "basis": "explicit_separation", "reason_ko": "참조는 물의 분출 부재에 관한 것인 반면, 후보는 등 능선에 작은 돌기/지느러미가 갑자기 나타나 형태가 변형되는 신체 특징 이상을 설명하므로 명백히 구분되는 현상입니다.", "separation_basis": "different_entity"}
  ]
}

